/**
 * Ed25519 key pairs Cindy creates for its own use (the dedicated key that reaches the person's own devices over
 * SSH). Generated by ssh2, so the private key is the standard unencrypted OpenSSH format that both Cindy's ssh2
 * client and the OpenSSH `ssh` command read from the same file. Writing the files (location, 0600) is the caller's
 * job; nothing here touches the disk.
 */
import { utils } from 'ssh2';

export interface OpenSshKeyPair {
  /** Unencrypted OpenSSH private-key block with a trailing newline. */
  privateKey: string;
  /** Canonical `ssh-ed25519 <base64>` (no comment). */
  publicKey: string;
}

/**
 * The OpenSSH wire form of an ed25519 public key: string "ssh-ed25519" then a 32-byte string. ssh2 drops a leading
 * zero byte of the key (about one key in 256), leaving a 31-byte key that OpenSSH and Cindy's own parsers reject.
 */
const CANONICAL_ED25519_BLOB = /^AAAAC3NzaC1lZDI1NTE5AAAAI[A-P][A-Za-z0-9+/]{42}$/;
/** Each attempt fails with probability 1/256, so this many in a row does not happen; it only bounds the loop. */
const MAX_ATTEMPTS = 8;

type Generate = (comment: string) => Promise<{ public: string; private: string }>;

const ssh2Generate: Generate = (comment) => new Promise((resolve, reject) => {
  utils.generateKeyPair('ed25519', { comment }, (error, pair) => {
    if (error) reject(error);
    else resolve(pair);
  });
});

export async function generateOpenSshEd25519KeyPair(comment: string, generate: Generate = ssh2Generate): Promise<OpenSshKeyPair> {
  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt += 1) {
    const pair = await generate(comment);
    const [type, blob] = pair.public.trim().split(/\s+/);
    if (type !== 'ssh-ed25519' || !blob) throw new Error('generated public key is not ssh-ed25519');
    // A shortened key: discard the whole pair (its private half carries the same public key) and generate again.
    if (!CANONICAL_ED25519_BLOB.test(blob)) continue;
    return { privateKey: pair.private, publicKey: `ssh-ed25519 ${blob}` };
  }
  throw new Error('could not generate a canonical ssh-ed25519 key');
}
